import{_ as t,o as a,c as i,ao as o}from"./chunks/framework.BGGFTQ95.js";const u=JSON.parse('{"title":"GEMB and IMAU-FDM","description":"","frontmatter":{},"headers":[],"relativePath":"imau_fdm_comparison.md","filePath":"imau_fdm_comparison.md","lastUpdated":null}'),n={name:"imau_fdm_comparison.md"};function r(s,e,d,c,l,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="GEMB-and-IMAU-FDM" tabindex="-1">GEMB and IMAU-FDM <a class="header-anchor" href="#GEMB-and-IMAU-FDM" aria-label="Permalink to &quot;GEMB and IMAU-FDM {#GEMB-and-IMAU-FDM}&quot;">​</a></h1><p><a href="https://github.com/IMAU-ice-and-climate/IMAU-FDM" target="_blank" rel="noreferrer">IMAU-FDM</a> (Ligtenberg et al., 2011; Brils et al., 2022) is the Utrecht Institute for Marine and Atmospheric Research firn densification model — ~3,900 lines of Fortran in <code>source/</code>, configured per domain through TOML (<code>FGRN055</code> for Greenland, <code>ANT27</code> for Antarctica). It is the third open firn model with a physics surface comparable to GEMB&#39;s, after the <a href="./cfm_comparison">Community Firn Model comparison</a>.</p><p>This page records a full read of IMAU-FDM&#39;s physics-bearing sources against GEMB&#39;s <code>src/</code>, in two directions: 2. <strong>What GEMB could take from it</strong> — two findings, both adopted.</p><ol start="3"><li><strong>Whether GEMB&#39;s existing physics agrees with an independent implementation</strong> — which produced more than the first direction did, including one place where IMAU-FDM&#39;s own source comments flag its version as a bug GEMB never had.</li></ol><p>IMAU-FDM is the <strong>narrower</strong> model of the two. It takes surface temperature as a prescribed Dirichlet boundary rather than solving an energy balance, and has no albedo, no shortwave penetration, no turbulent fluxes, and no grain-size state. Most of the capability surface is therefore GEMB-has/FDM-lacks and is not tabulated below; the interesting content is in the places where both models implement the <em>same</em> physics and disagree about it.</p><p>Citations point at IMAU-FDM as <code>firn_physics.f90:247</code> and at GEMB as <code>src/thermal_conductivity.jl</code>. Fortran line numbers are from the state of <code>main</code> read in August 2026.</p><h2 id="Summary" tabindex="-1">Summary <a class="header-anchor" href="#Summary" aria-label="Permalink to &quot;Summary {#Summary}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Physics</th><th style="text-align:right;">Verdict</th><th style="text-align:right;">Notes</th></tr></thead><tbody><tr><td style="text-align:right;">Calonne (2019) air-conductivity ratio</td><td style="text-align:right;"><strong>gap, adopted</strong></td><td style="text-align:right;">Finding 1 — new <code>:Calonne2019Air</code> method</td></tr><tr><td style="text-align:right;">Fausto (2018) fresh-snow density</td><td style="text-align:right;"><strong>gap, adopted</strong></td><td style="text-align:right;">Finding 2 — new <code>:FaustoFit</code> method</td></tr><tr><td style="text-align:right;">Coleou irreducible water content</td><td style="text-align:right;"><strong>GEMB correct</strong></td><td style="text-align:right;">GEMB never had the bug IMAU-FDM&#39;s own comment documents</td></tr><tr><td style="text-align:right;">Layer merging</td><td style="text-align:right;"><strong>GEMB correct</strong></td><td style="text-align:right;">GEMB merges on enthalpy; IMAU-FDM mass-weights temperature</td></tr><tr><td style="text-align:right;">Refreeze energy accounting</td><td style="text-align:right;"><strong>GEMB correct</strong></td><td style="text-align:right;">IMAU-FDM mixes <code>cp(T)</code> and <code>cp(T_melt)</code> in one budget</td></tr><tr><td style="text-align:right;">Densification reference temperature</td><td style="text-align:right;"><strong>GEMB correct</strong></td><td style="text-align:right;">IMAU-FDM uses the <em>bottom</em> layer; the paper, CFM and GEMB use mean annual surface</td></tr><tr><td style="text-align:right;">Spinup convergence criterion</td><td style="text-align:right;"><strong>GEMB richer</strong></td><td style="text-align:right;">GEMB tests drift slope as well as per-cycle delta</td></tr><tr><td style="text-align:right;">Heat capacity, physical constants</td><td style="text-align:right;"><strong>agreement</strong></td><td style="text-align:right;">same <code>152.5 + 7.122·T</code>, <code>g</code>, <code>Ec</code>, <code>Eg</code>, <code>ρ_i</code>, <code>T_melt</code></td></tr><tr><td style="text-align:right;">Ligtenberg <code>M0</code>/<code>M1</code> calibration</td><td style="text-align:right;"><strong>GEMB ahead</strong></td><td style="text-align:right;">9 calibration sets vs IMAU-FDM&#39;s 2</td></tr><tr><td style="text-align:right;">Implicit tridiagonal thermal solver</td><td style="text-align:right;"><strong>implemented</strong> (<code>ImplicitThermal</code>)</td><td style="text-align:right;">interior rows transferred; the surface row needed Newton — see below</td></tr></tbody></table><h2 id="What-GEMB-adopted" tabindex="-1">What GEMB adopted <a class="header-anchor" href="#What-GEMB-adopted" aria-label="Permalink to &quot;What GEMB adopted {#What-GEMB-adopted}&quot;">​</a></h2><p>Both findings land as <strong>new <code>Symbol</code> option values</strong>, leaving the defaults of the day bit-identical. Neither appears in the <a href="/GEMB.jl/previews/PR61/physics_notes#Physics-notes">Physics notes</a>, because neither changed a default when it was added. (<code>:Calonne2019</code> later <em>became</em> the default in v2.0.0, for the separate reasons recorded there.)</p><h3 id="Finding-1-—-:Calonne2019-omits-the-air-conductivity-ratio-of-eq.-5" tabindex="-1">Finding 1 — <code>:Calonne2019</code> omits the air-conductivity ratio of eq. 5 <a class="header-anchor" href="#Finding-1-—-:Calonne2019-omits-the-air-conductivity-ratio-of-eq.-5" aria-label="Permalink to &quot;Finding 1 — `:Calonne2019` omits the air-conductivity ratio of eq. 5 {#Finding-1-—-:Calonne2019-omits-the-air-conductivity-ratio-of-eq.-5}&quot;">​</a></h3><p>Calonne et al. (2019) eq. 5 blends a snow-regime and a firn-regime conductivity fit with a logistic weight in density, and rescales each by the constituent conductivities at the working temperature relative to their values at the temperature the fits were built at (270.15 K). The two regimes carry <strong>different</strong> scalings because they describe different microstructures: the firn fit describes a connected ice skeleton and scales with ice alone, while the snow fit describes grains suspended in air and scales with <em>both</em> constituents.</p><p>IMAU-FDM implements both factors (<code>firn_physics.f90:247-268</code>, <code>Thermal_Cond</code>):</p><div class="language-fortran vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">fortran</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kair = (2.334E-3*Temp**(3./2.))/(164.54 + Temp)          ! Reid (1966)</span></span>\n<span class="line"><span>kair_ref = (2.334E-3*270.15**(3./2.))/(164.54 + 270.15)</span></span>\n<span class="line"><span>ki = (1.-theta)*kice/kice_ref*kair/kair_ref*kcal + theta*kice/kice_ref*kf</span></span></code></pre></div><p>GEMB&#39;s <code>_thermal_conductivity_calonne2019</code> applied only the ice ratio, to both branches. Its docstring was explicit about this, because the implementation had been cross-checked against the CFM — which hardcodes <code>K_air = kref_a</code> in <code>diffusion.py</code> with the standing comment <em>&quot;at some point find equation for T-dependence of air&quot;</em>. GEMB inherited the CFM&#39;s simplification; <strong>IMAU-FDM is the only one of the three models that carries the term.</strong></p><p>Because air conducts less well as it cools, omitting the factor makes GEMB <strong>over-conduct cold snow</strong>. Measured ratio of <code>:Calonne2019</code> to the fuller form:</p><table tabindex="0"><thead><tr><th style="text-align:right;">T [K]</th><th style="text-align:right;"><code>kair/kair_ref</code></th><th style="text-align:right;">ρ=150</th><th style="text-align:right;">ρ=300</th><th style="text-align:right;">ρ=450</th><th style="text-align:right;">ρ=550</th><th style="text-align:right;">ρ=700</th></tr></thead><tbody><tr><td style="text-align:right;">220.0</td><td style="text-align:right;">0.8307</td><td style="text-align:right;">+20.4%</td><td style="text-align:right;">+20.4%</td><td style="text-align:right;">+9.9%</td><td style="text-align:right;">+0.28%</td><td style="text-align:right;">0%</td></tr><tr><td style="text-align:right;">233.15</td><td style="text-align:right;">0.8764</td><td style="text-align:right;">+14.1%</td><td style="text-align:right;">+14.1%</td><td style="text-align:right;">+7.0%</td><td style="text-align:right;">+0.20%</td><td style="text-align:right;">0%</td></tr><tr><td style="text-align:right;">253.15</td><td style="text-align:right;">0.9440</td><td style="text-align:right;">+5.9%</td><td style="text-align:right;">+5.9%</td><td style="text-align:right;">+3.1%</td><td style="text-align:right;">+0.09%</td><td style="text-align:right;">0%</td></tr><tr><td style="text-align:right;">270.15</td><td style="text-align:right;">1.0000</td><td style="text-align:right;">0%</td><td style="text-align:right;">0%</td><td style="text-align:right;">0%</td><td style="text-align:right;">0%</td><td style="text-align:right;">0%</td></tr></tbody></table><p>The bias vanishes at the reference temperature and above ρ ≈ 550, where the logistic weight hands over to the air-free firn branch. It is largest exactly in a cold, low-density polar winter surface layer — that is, exactly where the seasonal cold wave propagates — so it damps the winter surface signal.</p><p><code>mp.thermal_conductivity_method = :Calonne2019Air</code> selects the fuller form. <code>:Calonne2019</code> remains the default and is unchanged. Since the air term enters only as a <em>ratio</em>, Reid&#39;s absolute calibration cancels and only its temperature shape matters; continuity into ice is preserved because the factor is weighted by <code>(1-θ)</code>, which is ~1e-8 at ρ = 917.</p><p>One convention difference is worth recording: IMAU-FDM normalizes by the <em>computed</em> Yen (1981) value at 270.15 K, where GEMB and the CFM both use the published literal <code>2.107</code>. That is a uniform 1.15e-4 relative offset, it predates this addition, and it applies equally to <code>:Calonne2019</code>. GEMB keeps the literal.</p><h3 id="Finding-2-—-:Fausto-is-the-published-fit-frozen-at-one-temperature" tabindex="-1">Finding 2 — <code>:Fausto</code> is the published fit frozen at one temperature <a class="header-anchor" href="#Finding-2-—-:Fausto-is-the-published-fit-frozen-at-one-temperature" aria-label="Permalink to &quot;Finding 2 — `:Fausto` is the published fit frozen at one temperature {#Finding-2-—-:Fausto-is-the-published-fit-frozen-at-one-temperature}&quot;">​</a></h3><p>GEMB&#39;s <code>fresh_snow_density</code> returned a bare <code>315.0</code> for <code>:Fausto</code>, with no temperature dependence — unlike every other temperature-dependent option in the same function (<code>:Kaspers</code>, <code>:KuipersMunneke</code>), which all carry theirs. IMAU-FDM implements Fausto et al. (2018) as the actual regression (<code>initialise_model.f90:96</code>, <code>112</code>, <code>116</code>):</p><div class="language-fortran vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">fortran</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Rho0FM(step) = 362.1 + 2.78*(TempFM(step) - const%Tmelt)   ! Fausto et al. 2018</span></span></code></pre></div><p><code>362.1 + 2.78·(T − 273.15) = 315.0</code> at <strong>T ≈ 256.2 K</strong>. GEMB&#39;s constant is demonstrably this same fit evaluated at one plausible Greenland annual-mean temperature — not a different parameterization.</p><p><code>mp.new_snow_method = :FaustoFit</code> selects the regression; <code>:Fausto</code> still returns 315.0. Two implementation notes:</p><ul><li><p><code>fresh_snow_density</code> gained an <strong>optional fifth argument</strong>, the <em>instantaneous</em> air temperature, which only <code>:FaustoFit</code> reads. The function is shared by <code>calculate_accumulation</code> (which has <code>cfs.temperature_air</code>) and <code>steady_state_profile</code> (which has only a climatological mean), so the argument defaults to the mean: the transient site passes the instantaneous temperature while the steady-state march still gets a well-defined climatological ρ₀, and the four older methods are bit-identical either way.</p></li><li><p>The regression is <strong>unbounded below</strong> — it reaches zero at T ≈ 143 K — so the transient call site now clamps to <code>[1, ρ_i]</code>, mirroring the clamp <code>steady_state_profile</code> already applied. IMAU-FDM caps its <em>non</em>-Greenland fit at 470 but leaves the Fausto branch uncapped, so there is no upstream cap to copy.</p></li><li><p><code>:FaustoFit</code> also takes the Crocus (Vionnet et al., 2012) wind-dependent fresh-snow grain properties that <code>:Fausto</code> takes. That coupling is orthogonal to the density fit, and omitting it would have silently changed fresh-snow dendricity.</p></li></ul><h2 id="Consistency-findings-—-where-GEMB-is-correct-or-better" tabindex="-1">Consistency findings — where GEMB is correct or better <a class="header-anchor" href="#Consistency-findings-—-where-GEMB-is-correct-or-better" aria-label="Permalink to &quot;Consistency findings — where GEMB is correct or better {#Consistency-findings-—-where-GEMB-is-correct-or-better}&quot;">​</a></h2><p>These need no code changes. They are independent corroboration of GEMB&#39;s physics, recorded here so they are not re-litigated.</p><h3 id="Coleou-irreducible-water-—-GEMB-never-had-IMAU-FDM&#39;s-bug" tabindex="-1">Coleou irreducible water — GEMB never had IMAU-FDM&#39;s bug <a class="header-anchor" href="#Coleou-irreducible-water-—-GEMB-never-had-IMAU-FDM&#39;s-bug" aria-label="Permalink to &quot;Coleou irreducible water — GEMB never had IMAU-FDM&#39;s bug {#Coleou-irreducible-water-—-GEMB-never-had-IMAU-FDM&#39;s-bug}&quot;">​</a></h3><p><code>water_physics.f90:190-198</code> offers two variants of the Coleou &amp; Lesaffre (1998) irreducible water content. The one named <code>Coleou1998_corr</code> divides by <code>(1 − Wm)</code>, with the source comment <em>&quot;fixes known bug in FDM v1p2&quot;</em>; the uncorrected <code>Coleou1998_1p2</code> &quot;underestimates LWC&quot;. GEMB&#39;s <code>irreducible_saturation</code> (<code>src/calculate_melt.jl</code>) has always had the <code>wmi/(1-wmi)</code> correction. Two implementations arrived independently at the same wet-mass-versus-dry-mass subtlety, and GEMB was on the right side of it from the start.</p><h3 id="Layer-merging-—-GEMB-conserves-energy,-IMAU-FDM-does-not" tabindex="-1">Layer merging — GEMB conserves energy, IMAU-FDM does not <a class="header-anchor" href="#Layer-merging-—-GEMB-conserves-energy,-IMAU-FDM-does-not" aria-label="Permalink to &quot;Layer merging — GEMB conserves energy, IMAU-FDM does not {#Layer-merging-—-GEMB-conserves-energy,-IMAU-FDM-does-not}&quot;">​</a></h3><p><code>grid_routines.f90:54</code> merges two cells by mass-weighting <em>temperature</em>:</p><div class="language-fortran vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">fortran</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>T(k-1) = (T(k-1)*M(k-1) + T(k)*M(k))/(M(k-1)+M(k))</span></span></code></pre></div><p>That is not energy-conserving given IMAU-FDM&#39;s own temperature-dependent <code>c_p = 152.5 + 7.122·T</code>: the merged cell&#39;s enthalpy differs from the sum of its parts at second order in ΔT. GEMB&#39;s <code>manage_layer_thickness</code> merges through <code>specific_enthalpy</code>, which is exact for any <code>c_p(T)</code>.</p><p>The same defect appears in IMAU-FDM&#39;s refreeze routines (<code>water_physics.f90:34-45</code>, <code>151-158</code>), which compute the available energy with <code>cp</code> evaluated at the layer temperature but apply the resulting temperature increment with <code>cp0</code> evaluated at the melting point. GEMB carries enthalpy — never <code>T·c_p</code> — as the budget currency throughout, and its <code>verbose=true</code> per-timestep conservation checks would not survive the mixed-<code>c_p</code> form.</p><h3 id="Densification-reference-temperature-—-IMAU-FDM-is-the-outlier" tabindex="-1">Densification reference temperature — IMAU-FDM is the outlier <a class="header-anchor" href="#Densification-reference-temperature-—-IMAU-FDM-is-the-outlier" aria-label="Permalink to &quot;Densification reference temperature — IMAU-FDM is the outlier {#Densification-reference-temperature-—-IMAU-FDM-is-the-outlier}&quot;">​</a></h3><p><code>Densific</code> evaluates the grain-growth Arrhenius term at <code>T(1)</code>, the <strong>bottom</strong> layer of the column (<code>firn_physics.f90:323</code>, <code>329</code>). Arthern et al. (2010) specifies mean annual <em>surface</em> temperature; the CFM uses <code>self.T_mean</code> (surface, <code>physics.py:334</code>); GEMB uses <code>tam</code> (<code>src/calculate_density.jl</code>). Two of three implementations agree with the paper.</p><p>IMAU-FDM&#39;s choice is defensible as a steady-state identity — at deep-column equilibrium the bottom temperature approaches the mean annual surface temperature — but it is not the published form, and it couples densification to the basal boundary condition during transients.</p><h3 id="Spinup-convergence-—-GEMB&#39;s-criterion-is-richer" tabindex="-1">Spinup convergence — GEMB&#39;s criterion is richer <a class="header-anchor" href="#Spinup-convergence-—-GEMB&#39;s-criterion-is-richer" aria-label="Permalink to &quot;Spinup convergence — GEMB&#39;s criterion is richer {#Spinup-convergence-—-GEMB&#39;s-criterion-is-richer}&quot;">​</a></h3><p>IMAU-FDM iterates on the squared change in surface elevation <em>and</em> in firn air content between cycles (<code>time_loop.f90:57</code>, <code>129-130</code>), with bounds 0.0001 (FGRN055) / 0.004 (ANT27) and 3–70 or 3–200 cycles. GEMB&#39;s <code>gemb_spinup</code> (<code>src/spinup.jl</code>) tests <strong>both</strong> a per-cycle delta <em>and</em> a least-squares drift slope over a window — precisely because, as its own docstring says, &quot;a column creeping steadily at just under the tolerance passes&quot; a delta-only test. That is the exact weakness of IMAU-FDM&#39;s criterion.</p><p>This also resolves an open question left by the CFM pass: the benchmark&#39;s <code>converged = false</code> after 75 cycles is because <code>bench/opt_bench.jl</code> passes <strong>no</strong> convergence criteria at all, so <code>checking = false</code> and the flag is never set. It was never a convergence failure.</p><h3 id="Heat-capacity-and-constants-—-agreement" tabindex="-1">Heat capacity and constants — agreement <a class="header-anchor" href="#Heat-capacity-and-constants-—-agreement" aria-label="Permalink to &quot;Heat capacity and constants — agreement {#Heat-capacity-and-constants-—-agreement}&quot;">​</a></h3><p>GEMB&#39;s <code>:CuffeyPaterson</code> heat capacity is the same <code>152.5 + 7.122·T</code> IMAU-FDM hardcodes throughout. <code>g = 9.81</code>, <code>Ec = 60000</code>, <code>Eg = 42400</code>, <code>ρ_i = 917</code>, <code>T_melt = 273.15</code> all match (<code>settings/*/constants.toml</code>). IMAU-FDM&#39;s <code>days_per_year = 365.25</code> against GEMB&#39;s deliberate <code>DAYS_PER_YEAR_DENSIFICATION = 365.0</code> is the ~0.07% standing offset already recorded in the <a href="/GEMB.jl/previews/PR61/physics_notes#Physics-notes">Physics notes</a> as deviation 4 — no new action.</p><h2 id="Adopted-later-—-numerics" tabindex="-1">Adopted later — numerics <a class="header-anchor" href="#Adopted-later-—-numerics" aria-label="Permalink to &quot;Adopted later — numerics {#Adopted-later-—-numerics}&quot;">​</a></h2><h3 id="Implicit-tridiagonal-thermal-solver-—-implemented,-with-the-surface-row-resolved" tabindex="-1">Implicit tridiagonal thermal solver — implemented, with the surface row resolved <a class="header-anchor" href="#Implicit-tridiagonal-thermal-solver-—-implemented,-with-the-surface-row-resolved" aria-label="Permalink to &quot;Implicit tridiagonal thermal solver — implemented, with the surface row resolved {#Implicit-tridiagonal-thermal-solver-—-implemented,-with-the-surface-row-resolved}&quot;">​</a></h3><p>This finding is now closed, and the prediction it made held up: the interior rows transferred directly, and the surface row was the entire difficulty.</p><p>IMAU-FDM&#39;s <code>Solve_Temp_Imp</code> (<code>firn_physics.f90:169-241</code>) is attractively compact: ~70 lines, θ-weighted, Thomas algorithm, following Versteeg &amp; Malalasekera. It is <strong>not</strong> a drop-in, for the reason recorded here originally. Line 219 builds the surface boundary as <code>Su = 2·kip·Ts/DZ</code> — a <em>prescribed</em> Dirichlet surface temperature. GEMB solves a nonlinear surface energy balance (longwave, turbulent fluxes), plus shortwave penetrating to depth, so the surface row needs linearization and outer iteration, and the shortwave source has no analogue in IMAU-FDM&#39;s tridiagonal at all. The bottom boundary does match: both models hold a fixed bottom cell.</p><p>GEMB&#39;s <code>ImplicitThermal</code> (<code>src/calculate_temperature.jl</code>) resolves the surface row with Newton rather than lagged Picard — a lagged surface flux <em>diverges</em>, since the fixed-point gain <code>|dQ/dT₁|·Δt/(M₁c)</code> exceeds 1 for a centimetre-scale surface cell at any Δt of interest. The flux is linearized into the diagonal as <code>Q(T₁) ≈ Q_k + Λ_k(T₁ − T_{1,k})</code> with <code>Λ ≤ 0</code>, which <em>strengthens</em> diagonal dominance. Because <code>Q_k</code> is the true nonlinear flux at the iterate, the two <code>Λ</code> terms cancel at convergence, so the slope&#39;s accuracy affects only the convergence rate and never the converged answer.</p><p>Being confined to row 1, the nonlinearity also permits static condensation: the interior is eliminated bottom-up once per sub-step and Newton iterates on a single scalar equation, which measured 2.67× faster than re-sweeping the column per iteration.</p><p><code>ExplicitThermal</code> remains the default and is bit-identical to before. The implicit path is 2.4× <em>slower</em> on a well-conditioned column (5.75 s vs 2.44 s over a year of 3-hourly forcing); its value is that its cost is independent of the stiffest cell. See <a href="./cfm_comparison">the CFM page</a> for the full measurements.</p><p>Both of the choices this section turns on were independently arrived at by Fourteau et al. (2024), whose framework for coupling a melting-surface energy balance to a finite-volume heat equation was published while this comparison was open. Their Newton-with-Schur-complement (their eqs. 11–13, and Appendix B, which notes the reduction applies to models of GEMB&#39;s class) is the same construction as the Newton solve on a single scalar after static condensation described above, derived independently. Their Sect. 6.4 also quantifies what IMAU-FDM&#39;s prescribed Dirichlet surface temperature costs: a spurious energy flux of −14.5 W m⁻² for a melting glacier surface, changing ablation by 40%. That is the strongest available argument for the flux-based application GEMB uses on both paths. See <a href="/GEMB.jl/previews/PR61/index#Surface-energy-balance-numerics">Surface energy balance numerics</a>.</p><h2 id="Deliberately-not-adopted" tabindex="-1">Deliberately not adopted <a class="header-anchor" href="#Deliberately-not-adopted" aria-label="Permalink to &quot;Deliberately not adopted {#Deliberately-not-adopted}&quot;">​</a></h2><h3 id="numSnow-window-averaged-temperature" tabindex="-1"><code>numSnow</code> window-averaged temperature <a class="header-anchor" href="#numSnow-window-averaged-temperature" aria-label="Permalink to &quot;`numSnow` window-averaged temperature {#numSnow-window-averaged-temperature}&quot;">​</a></h3><p>IMAU-FDM optionally drives fresh-snow density from a temperature averaged over a recent-snowfall window (<code>initialise_model.f90:104-134</code>). That is a smoothing choice, not new physics, and the <code>fresh_snow_density</code> signature change in Finding 2 makes either input expressible if it is ever wanted.</p><h3 id="Domain-specific-MO-recalibration" tabindex="-1">Domain-specific <code>MO</code> recalibration <a class="header-anchor" href="#Domain-specific-MO-recalibration" aria-label="Permalink to &quot;Domain-specific `MO` recalibration {#Domain-specific-MO-recalibration}&quot;">​</a></h3><p><code>Densific</code> (<code>firn_physics.f90:288-315</code>) recalibrates its densification multiplier per domain, e.g. <code>MO_low = 0.7522 − 0.0178·log(acav)</code> for Greenland. This is the direct analogue of GEMB&#39;s Ligtenberg <code>M0</code>/<code>M1</code> (<code>src/densification_lookup.jl</code>), which already carries <strong>nine</strong> calibration sets across Antarctica and Greenland against IMAU-FDM&#39;s two. GEMB is ahead here, and the fits are not interchangeable — different forcing products, and a different Arrhenius reference temperature per the point above — so cross-importing coefficients would be unsound.</p><h3 id="Bottom-of-column-layer-add/delete" tabindex="-1">Bottom-of-column layer add/delete <a class="header-anchor" href="#Bottom-of-column-layer-add/delete" aria-label="Permalink to &quot;Bottom-of-column layer add/delete {#Bottom-of-column-layer-add/delete}&quot;">​</a></h3><p><code>Add_Layers</code> / <code>Delete_Layers</code> grow and shrink IMAU-FDM&#39;s column in 100- or 200-layer blocks. GEMB&#39;s fixed-count, fixed-depth column with its two <code>grid_ops.jl</code> controllers is a deliberate and documented alternative, not a gap.</p><h3 id="Ice-shelf-buoyancy" tabindex="-1">Ice-shelf buoyancy <a class="header-anchor" href="#Ice-shelf-buoyancy" aria-label="Permalink to &quot;Ice-shelf buoyancy {#Ice-shelf-buoyancy}&quot;">​</a></h3><p><code>vbouy</code> (<code>firn_physics.f90:106-113</code>) is a floating-ice elevation diagnostic, outside a column mass-balance model&#39;s remit. GEMB&#39;s <code>apply_horizontal_strain!</code> covers the ice-dynamic coupling it does model.</p><h2 id="References" tabindex="-1">References <a class="header-anchor" href="#References" aria-label="Permalink to &quot;References {#References}&quot;">​</a></h2><ul><li><p>Brils, M., Kuipers Munneke, P., van de Berg, W. J., and van den Broeke, M. (2022). Improved representation of the contemporary Greenland ice sheet firn layer by IMAU-FDM v1.2G. <em>Geoscientific Model Development</em>, 15, 7121–7138.</p></li><li><p>Ligtenberg, S. R. M., Helsen, M. M., and van den Broeke, M. R. (2011). An improved semi-empirical model for the densification of Antarctic firn. <em>The Cryosphere</em>, 5, 809–819.</p></li><li><p>Calonne, N., Milliancourt, L., Burr, A., Philip, A., Martin, C. L., Flin, F., and Geindreau, C. (2019). Thermal conductivity of snow, firn, and porous ice from 3-D image-based computations. <em>Geophysical Research Letters</em>, 46, 13079–13089.</p></li><li><p>Reid, R. C., Prausnitz, J. M., and Sherwood, T. K. (1966). <em>The Properties of Gases and Liquids</em>. McGraw-Hill.</p></li><li><p>Yen, Y.-C. (1981). <em>Review of thermal properties of snow, ice and sea ice</em>. CRREL Report 81-10.</p></li><li><p>Fausto, R. S., Box, J. E., Vandecrux, B., van As, D., Steffen, K., MacFerrin, M. J., Machguth, H., and Colgan, W. (2018). A snow density dataset for improving surface boundary conditions in Greenland ice sheet firn modeling. <em>Frontiers in Earth Science</em>, 6, 51.</p></li><li><p>Coleou, C., and Lesaffre, B. (1998). Irreducible water saturation in snow: experimental results in a cold laboratory. <em>Annals of Glaciology</em>, 26, 64–68.</p></li><li><p>Arthern, R. J., Vaughan, D. G., Rankin, A. M., Mulvaney, R., and Thomas, E. R. (2010). In situ measurements of Antarctic snow compaction compared with predictions of models. <em>Journal of Geophysical Research</em>, 115, F03011.</p></li><li><p>Vionnet, V., Brun, E., Morin, S., Boone, A., Faroux, S., Le Moigne, P., Martin, E., and Willemet, J.-M. (2012). The detailed snowpack scheme Crocus and its implementation in SURFEX v7.2. <em>Geoscientific Model Development</em>, 5, 773–791.</p></li><li><p>Versteeg, H. K., and Malalasekera, W. (2007). <em>An Introduction to Computational Fluid Dynamics: The Finite Volume Method</em>, 2nd ed. Pearson.</p></li><li><p>Fourteau, K., Brondex, J., Brun, F., and Dumont, M. (2024). A novel numerical implementation for the surface energy budget of melting snowpacks and glaciers. <em>Geoscientific Model Development</em>, 17, 1903–1929.</p></li></ul>',62)])])}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
